o=format&fit=crop&w=1000&h=800&q=85',0,2,'Front Elevation Angle','2026-09-22 17:08:27'),(438,88,'https://images.unsplash.com/photo-1672518194432-4c23cbcec1c4?auto=format&fit=crop&w=800&h=800&q=90',0,3,'Material Texture Detail','2026-09-22 17:08:27'),(439,88,'https://images.unsplash.com/photo-1672518194432-4c23cbcec1c4?auto=format&fit=crop&w=900&h=750&q=85',0,4,'Joinery & Craft Detail','2026-09-22 17:08:27'),(440,88,'https://images.unsplash.com/photo-1672518194432-4c23cbcec1c4?auto=format&fit=crop&w=1200&h=900&q=85',0,5,'Ambient Room Perspective','2026-09-22 17:08:27'),(441,89,'/gruhu/assets/uploads/products/atelier_1790100871742_1980c886.webp',1,1,'Studio Full View','2026-09-22 23:44:31');
/*!40000 ALTER TABLE `product_images` ENABLE KEYS */;
UNLOCK TABLES;
DROP TABLE IF EXISTS `products`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `products` (
  `product_id` int NOT NULL AUTO_INCREMENT,
  `category_id` int NOT NULL,
  `subcategory_id` int DEFAULT NULL,
  `product_name` varchar(200) NOT NULL,
  `description` text NOT NULL,
  `price` decimal(10,2) NOT NULL,
  `discount_percent` decimal(5,2) DEFAULT '0.00',
  `stock_quantity` int NOT NULL DEFAULT '10',
  `material` varchar(100) DEFAULT NULL,
  `color` varchar(50) DEFAULT NULL,
  `size` varchar(100) DEFAULT NULL,
  `dimensions` varchar(100) DEFAULT NULL,
  `style` varchar(100) DEFAULT NULL,
  `brand` varchar(100) DEFAULT 'Gruhu Atelier',
  `rating` decimal(2,1) DEFAULT '4.9',
  `is_featured` tinyint(1) DEFAULT '0',
  `status` varchar(20) DEFAULT 'ACTIVE',
  `rooms` varchar(120) DEFAULT 'living_room,hall',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `delivery_option` varchar(100) DEFAULT 'Complimentary White-Glove Delivery',
  PRIMARY KEY (`product_id`),
  KEY `category_id` (`category_id`),
  KEY `subcategory_id` (`subcategory_id`),
  CONSTRAINT `products_ibfk_1` FOREIGN KEY (`category_id`) REFERENCES `categories` (`category_id`),
  CONSTRAINT `products_ibfk_2` FOREIGN KEY (`subcategory_id`) REFERENCES `subcategories` (`subcategory_id`)
) ENGINE=InnoDB AUTO_INCREMENT=90 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `products` WRITE;
/*!40000 ALTER TABLE `products` DISABLE KEYS */;
INSERT INTO `products` VALUES (1,1,1,'Koto Boucle 2-Seater Loveseat','The Koto 2-Seater Loveseat brings intimate architectural comfort to compact living quarters. Wrapped in heavy-weight Italian wool boucle with a warm, tactile hand feel, its rounded contours are elevated by recessed solid oak legs. Handcrafted using double-doweled FSC beech framing and multi-density foam core.',38999.00,10.00,18,'Textured Wool Boucle & Solid Oak','Ivory Cream',NULL,'165 x 88 x 78 cm',NULL,'Gruhu Atelier',4.9,1,'ACTIVE','living_room,hall','2026-09-22 17:08:25','2026-09-23 03:26:26','Complimentary White-Glove Delivery'),(2,1,1,'Arne Scandinavian 2-Seater Flax Sofa','Rooted in classic mid-century Danish proportion, the Arne 2-Seater is tailored in pure Belgian washed flax linen. Features crisp French flange seam detailing, feather-down wrapped seat cushions, and turned tapered legs in clear-lacquered solid white oak.',34999.00,5.00,15,'Belgian Flax Linen & White Oak','Natural Oatmeal',NULL,'170 x 86 x 76 cm',NULL,'Gruhu Atelier',4.9,0,'ACTIVE','living_room,hall','2026-09-22 17:08:25','2026-09-22 17:08:25','Complimentary White-Glove Delivery'),(3,1,1,'Fjord Compact 2-Seater Pebble Sofa','Sculpted with organic pebble curves, the Fjord Compact Sofa balances architectural restraint with inviting ergonomics. Upholstered in hardwearing Melange wool blend with water-repellent finishing, grounded by recessed conical smoked ash feet.',36499.00,8.00,14,'Nordic Wool Weave & Smoked Ash','Pebble Grey',NULL,'160 x 84 x 75 cm',NULL,'Gruhu Atelier',4.9,0,'ACTIVE','living_room,hall','2026-09-22 17:08:25','2026-09-22 23:20:35','Complimentary White-Glove Delivery'),(4,1,1,'Astrid Atelier 3-Seater Tailored Sofa','A centerpiece for expansive living rooms, the Astrid 3-Seater combines a single continuous bench seat with architectural knife-edge tailoring. Supported by an under-slung American walnut perimeter apron with integrated center bracing.',54999.00,12.00,15,'Textured Wool Twill & Solid Walnut','Warm